import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {createChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {ToolRegistry} from '../../orchestration/tools/registry.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../../types/ai.js';
import type {ChatSession, SessionSummary} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionStore} from '../../types/sessionStore.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {validateMessage} from './validation.js';

const text = (value: string): MessageChunk => ({type: 'text', text: value});
const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

interface MessageHandlerHarness {
  session: ChatSession;
  sent: OutgoingMessage[];
  send: (raw: unknown, options?: {userId?: string}) => Promise<void>;
  frames: () => string[];
}

const createHarness = (orchestrator: ChatOrchestrator): MessageHandlerHarness => {
  const sent: OutgoingMessage[] = [];
  const ws = {
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
  } as unknown as WebSocket;

  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  const handle = createMessageHandler(orchestrator);

  const wire = (messages: OutgoingMessage[]): string[] =>
    messages.map(frame => {
      if (frame.type === 'conversation_list') {
        return `conversation_list ${frame.conversations.length}`;
      }
      if (frame.type === 'error') {
        return `error ${frame.code}`;
      }
      if (frame.type === 'pong') return `pong ${frame.timestamp}`;
      if (frame.type === 'stream_end') return 'stream_end';
      return frame.type;
    });

  return {
    session,
    sent,
    frames: () => wire(sent),
    send: async (raw: unknown, options?: {userId?: string}) => {
      if (options?.userId) {
        (ws as unknown as {userId: string}).userId = options.userId;
      } else if (!('userId' in ws)) {
        (ws as unknown as {userId: string}).userId = 'u1';
      }
      await handle(ws, session, raw);
    },
  };
};

describe('conversation list over WebSocket', () => {
  describe('validation', () => {
    it('accepts list_conversations with no fields', () => {
      const result = validateMessage({type: 'list_conversations'});
      expect(result.valid).toBe(true);
    });

    it('rejects list_conversations with limit: 0', () => {
      const result = validateMessage({type: 'list_conversations', limit: 0});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit: 201', () => {
      const result = validateMessage({type: 'list_conversations', limit: 201});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit: 1.5', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1.5});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit as string', () => {
      const result = validateMessage({type: 'list_conversations', limit: '10'});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with before as invalid date string', () => {
      const result = validateMessage({type: 'list_conversations', before: 'not a date'});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('accepts list_conversations with valid limit', () => {
      const result = validateMessage({type: 'list_conversations', limit: 10});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with limit: 1', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with limit: 200', () => {
      const result = validateMessage({type: 'list_conversations', limit: 200});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with valid ISO date before', () => {
      const isoDate = new Date().toISOString();
      const result = validateMessage({type: 'list_conversations', before: isoDate});
      expect(result.valid).toBe(true);
    });
  });

  describe('message handler response', () => {
    it('returns error UNSUPPORTED when history is not enabled', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: new InMemorySessionStore(),
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('error UNSUPPORTED');
    });

    it('returns conversation_list when history is enabled and store has listFor', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([
          {
            sessionId: 's1',
            createdAt: new Date('2026-01-01'),
            updatedAt: new Date('2026-01-02'),
            entryCount: 5,
          },
          {
            sessionId: 's2',
            createdAt: new Date('2025-12-01'),
            updatedAt: new Date('2025-12-15'),
            entryCount: 3,
          },
          {
            sessionId: 's3',
            createdAt: new Date('2025-11-01'),
            updatedAt: new Date('2025-11-20'),
            entryCount: 10,
          },
        ] as SessionSummary[]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('conversation_list 3');
      const listMessage = harness.sent.find(m => m.type === 'conversation_list');
      expect(listMessage).toBeDefined();
      if (listMessage && 'conversations' in listMessage) {
        expect(listMessage.conversations.length).toBe(3);
        expect(listMessage.conversations[0].sessionId).toBe('s1');
        expect(typeof listMessage.conversations[0].createdAt).toBe('string');
        expect(typeof listMessage.conversations[0].updatedAt).toBe('string');
      }
    });

    it('uses ws.userId for the store query, not frame userId', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations', userId: 'u2'}, {userId: 'u1'});

      expect(mockStore.listFor).toHaveBeenCalledWith('u1', expect.anything());
    });

    it('passes limit and before to store listFor', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);
      const isoDate = new Date().toISOString();

      await harness.send({type: 'list_conversations', limit: 50, before: isoDate});

      expect(mockStore.listFor).toHaveBeenCalledWith('u1', {limit: 50, before: isoDate});
    });

    it('returns error UNSUPPORTED when store has no listFor method', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('error UNSUPPORTED');
    });

    it('returns error SERVER_ERROR when store listFor rejects', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
