import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {createChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {ToolRegistry} from '../../orchestration/tools/registry.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../../types/ai.js';
import type {ChatSession, SessionSummary} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionStore} from '../../types/sessionStore.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {validateMessage} from './validation.js';

const text = (value: string): MessageChunk => ({type: 'text', text: value});
const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

interface MessageHandlerHarness {
  session: ChatSession;
  sent: OutgoingMessage[];
  send: (raw: unknown, options?: {userId?: string}) => Promise<void>;
  frames: () => string[];
}

const createHarness = (orchestrator: ChatOrchestrator): MessageHandlerHarness => {
  const sent: OutgoingMessage[] = [];
  const ws = {
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
  } as unknown as WebSocket;

  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  const handle = createMessageHandler(orchestrator);

  const wire = (messages: OutgoingMessage[]): string[] =>
    messages.map(frame => {
      if (frame.type === 'conversation_list') {
        return `conversation_list ${frame.conversations.length}`;
      }
      if (frame.type === 'error') {
        return `error ${frame.code}`;
      }
      if (frame.type === 'pong') return `pong ${frame.timestamp}`;
      if (frame.type === 'stream_end') return 'stream_end';
      return frame.type;
    });

  return {
    session,
    sent,
    frames: () => wire(sent),
    send: async (raw: unknown, options?: {userId?: string}) => {
      if (options?.userId) {
        (ws as unknown as {userId: string}).userId = options.userId;
      } else if (!('userId' in ws)) {
        (ws as unknown as {userId: string}).userId = 'u1';
      }
      await handle(ws, session, raw);
    },
  };
};

describe('conversation list over WebSocket', () => {
  describe('validation', () => {
    it('accepts list_conversations with no fields', () => {
      const result = validateMessage({type: 'list_conversations'});
      expect(result.valid).toBe(true);
    });

    it('rejects list_conversations with limit: 0', () => {
      const result = validateMessage({type: 'list_conversations', limit: 0});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit: 201', () => {
      const result = validateMessage({type: 'list_conversations', limit: 201});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit: 1.5', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1.5});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with limit as string', () => {
      const result = validateMessage({type: 'list_conversations', limit: '10'});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('rejects list_conversations with before as invalid date string', () => {
      const result = validateMessage({type: 'list_conversations', before: 'not a date'});
      expect(result.valid).toBe(false);
      expect(result).toHaveProperty('error');
    });

    it('accepts list_conversations with valid limit', () => {
      const result = validateMessage({type: 'list_conversations', limit: 10});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with limit: 1', () => {
      const result = validateMessage({type: 'list_conversations', limit: 1});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with limit: 200', () => {
      const result = validateMessage({type: 'list_conversations', limit: 200});
      expect(result.valid).toBe(true);
    });

    it('accepts list_conversations with valid ISO date before', () => {
      const isoDate = new Date().toISOString();
      const result = validateMessage({type: 'list_conversations', before: isoDate});
      expect(result.valid).toBe(true);
    });
  });

  describe('message handler response', () => {
    it('returns error UNSUPPORTED when history is not enabled', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
