            sessionId: 's1',
            createdAt: new Date('2026-01-01'),
            updatedAt: new Date('2026-01-02'),
            entryCount: 5,
          },
          {
            sessionId: 's2',
            createdAt: new Date('2025-12-01'),
            updatedAt: new Date('2025-12-15'),
            entryCount: 3,
          },
          {
            sessionId: 's3',
            createdAt: new Date('2025-11-01'),
            updatedAt: new Date('2025-11-20'),
            entryCount: 10,
          },
        ] as SessionSummary[]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('conversation_list 3');
      const listMessage = harness.sent.find(m => m.type === 'conversation_list');
      expect(listMessage).toBeDefined();
      if (listMessage && 'conversations' in listMessage) {
        expect(listMessage.conversations.length).toBe(3);
        expect(listMessage.conversations[0].sessionId).toBe('s1');
        expect(typeof listMessage.conversations[0].createdAt).toBe('string');
        expect(typeof listMessage.conversations[0].updatedAt).toBe('string');
      }
    });

    it('uses ws.userId for the store query, not frame userId', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations', userId: 'u2'}, {userId: 'u1'});

      expect(mockStore.listFor).toHaveBeenCalledWith('u1', expect.anything());
    });

    it('passes limit and before to store listFor', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);
      const isoDate = new Date().toISOString();

      await harness.send({type: 'list_conversations', limit: 50, before: isoDate});

      expect(mockStore.listFor).toHaveBeenCalledWith('u1', {limit: 50, before: isoDate});
    });

    it('returns error UNSUPPORTED when store has no listFor method', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
