        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('error UNSUPPORTED');
    });

    it('returns error SERVER_ERROR when store listFor rejects', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockRejectedValue(new Error('database connection failed')),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).toContain('error SERVER_ERROR');
    });

    it('includes no stream_end after conversation_list', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
        generateStructured: jest.fn(),
      } as unknown as AIProvider;

      const mockStore = {
        create: jest.fn(),
        get: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
        clear: jest.fn(),
        listFor: jest.fn().mockResolvedValue([]),
      } as unknown as SessionStore;

      const orchestrator = createChatOrchestrator(mockProvider, new PromptBuilder({}), new ToolRegistry(), {
        sessionStore: mockStore,
      });

      const harness = createHarness(orchestrator);

      await harness.send({type: 'list_conversations'});

      expect(harness.frames()).not.toContain('stream_end');
    });

    it('returns conversation metadata as ISO strings', async () => {
      const mockProvider = {
        sendMessage: jest.fn(),
